#include <WiFi.h>
#include <WebServer.h>

const char* ssid = "YOUR_WIFI_SSID";
const char* password = "YOUR_WIFI_PASSWORD";
WebServer server(80);
const int ledPin = 2;
bool ledState = false;

void handleOn() { digitalWrite(ledPin, HIGH); ledState = true; server.send(200, "text/plain", "ON"); }
void handleOff() { digitalWrite(ledPin, LOW); ledState = false; server.send(200, "text/plain", "OFF"); }

void setup() {
  Serial.begin(115200);
  pinMode(ledPin, OUTPUT);
  digitalWrite(ledPin, LOW);
  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) { delay(500); Serial.print("."); }
  server.on("/api/on", handleOn);
  server.on("/api/off", handleOff);
  server.begin();
}
void loop() { server.handleClient(); }

#include <AdafruitIO_WiFi.h>
#define WIFI_SSID "YOUR_WIFI_SSID"
#define WIFI_PASS "YOUR_WIFI_PASSWORD"
#define IO_USERNAME "YOUR_ADAFRUIT_IO_USERNAME"
#define IO_KEY "YOUR_ADAFRUIT_IO_KEY"
AdafruitIO_WiFi io(IO_USERNAME, IO_KEY, WIFI_SSID, WIFI_PASS);
AdafruitIO_Feed *esp = io.feed("esp");
#define RELAY_PIN 26
#define RELAY_ON HIGH
#define RELAY_OFF LOW
void handleESPMessage(AdafruitIO_Data *data) { String command = data->toString(); command.trim(); command.toUpperCase(); if (command == "ON") digitalWrite(RELAY_PIN, RELAY_ON); else if (command == "OFF") digitalWrite(RELAY_PIN, RELAY_OFF); }
void setup() { Serial.begin(115200); pinMode(RELAY_PIN, OUTPUT); digitalWrite(RELAY_PIN, RELAY_OFF); esp->onMessage(handleESPMessage); io.connect(); while (io.status() < AIO_CONNECTED) { delay(500); } esp->get(); }
void loop() { io.run(); }

