#include <DHT.h>
#include <Firebase_ESP_Client.h>
#define DHT_PIN 4
#define LDR_PIN 34
#define RELAY_PIN 26
#define SENSOR_INTERVAL 2000
DHT dht(DHT_PIN, DHT11);
FirebaseData fbdo;
FirebaseAuth auth;
FirebaseConfig config;
int ldrThreshold = 2500;
bool relayState = false;
String mode = "manual";
void applyRelay(bool state) { relayState = state; digitalWrite(RELAY_PIN, state ? LOW : HIGH); }
void setup() { Serial.begin(115200); pinMode(RELAY_PIN, OUTPUT); digitalWrite(RELAY_PIN, HIGH); dht.begin(); Firebase.begin(&config, &auth); }
void loop() { float temperature = dht.readTemperature(); float humidity = dht.readHumidity(); int ldrValue = analogRead(LDR_PIN); FirebaseJson json; json.set("temperature", temperature); json.set("humidity", humidity); json.set("ldr", ldrValue); json.set("bulbState", relayState); json.set("mode", mode); Firebase.RTDB.pushJSON(&fbdo, "/sensorData", &json); delay(SENSOR_INTERVAL); }
